// Return a React component. Available props:
//   properties, styles
//   variables, components, scripts, tables, commands, page
//   runEvent(type)              - fire a configured component event
//   setVariable(name, value)    - write a device variable
//   executeCommand(name, value) - run a device command
//   runScript(idOrName)         - run a page JavaScript script

function Component({
  variables,
  components,
  runEvent,
  executeCommand,
  setVariable,
  tables,
  globals,
  setGlobal,
  runScript,
  scripts
}) {

  const createDefaultAlarmRule = (inputId) => ({
    INPUT_ID: inputId,
    INPUT_NAME: `GPIO_${inputId}`,
    CLEAR_DELAY_TICKS: 10,
    DEBOUNCE_TICKS: 5,
    RETRY_PROFILE_ID: 0,
    SEND_RECOVERY_EMAIL: 1,
    TRIGGER_HIGH: 1,
    TRIGGER_LOW: 1,
    TRIGGER_TYPE: 1
  });

  const areAlarmRuleSetsEqual = (set1, set2) => {
    const list1 = set1 || [];
    const list2 = set2 || [];

    if (list1.length !== list2.length) {
      return false;
    }

    const sortedSet1 = [...list1].sort(
      (a, b) => Number(a.INPUT_ID) - Number(b.INPUT_ID)
    );

    const sortedSet2 = [...list2].sort(
      (a, b) => Number(a.INPUT_ID) - Number(b.INPUT_ID)
    );

    for (let i = 0; i < sortedSet1.length; i++) {
      const rule1 = sortedSet1[i];
      const rule2 = sortedSet2[i];

      if (
        Number(rule1.INPUT_ID) !== Number(rule2.INPUT_ID) ||
        (rule1.INPUT_NAME || '') !== (rule2.INPUT_NAME || '') ||
        Number(rule1.CLEAR_DELAY_TICKS) !== Number(rule2.CLEAR_DELAY_TICKS) ||
        Number(rule1.DEBOUNCE_TICKS) !== Number(rule2.DEBOUNCE_TICKS) ||
        Number(rule1.RETRY_PROFILE_ID) !== Number(rule2.RETRY_PROFILE_ID) ||
        Number(rule1.SEND_RECOVERY_EMAIL) !== Number(rule2.SEND_RECOVERY_EMAIL) ||
        Number(rule1.TRIGGER_HIGH) !== Number(rule2.TRIGGER_HIGH) ||
        Number(rule1.TRIGGER_LOW) !== Number(rule2.TRIGGER_LOW) ||
        Number(rule1.TRIGGER_TYPE) !== Number(rule2.TRIGGER_TYPE)
      ) {
        return false;
      }
    }

    return true;
  };

  // Update one field on an existing alarm rule
  const updateAlarmRuleField = (
    inputId,
    fieldName,
    value
  ) => {
    const currentAlarmRules =
      globals.new_alarm_rules
        ? [...globals.new_alarm_rules]
        : [];

    const index = currentAlarmRules.findIndex(
      rule => Number(rule.INPUT_ID) === inputId
    );

    if (index === -1) {
      return;
    }

    const updatedRule = {
      ...currentAlarmRules[index],
      [fieldName]: value
    };

    const newAlarmRules = [
      ...currentAlarmRules.slice(0, index),
      updatedRule,
      ...currentAlarmRules.slice(index + 1)
    ];

    setGlobal(
      'new_alarm_rules',
      newAlarmRules
    );
  };

  // Monitor whether the editable table differs from the original
  React.useEffect(() => {
    const changed = !areAlarmRuleSetsEqual(
      globals.initial_alarm_rules,
      globals.new_alarm_rules
    );

    if (changed !== globals.alarm_rules_changed) {
      setGlobal(
        'alarm_rules_changed',
        changed
      );
    }
  }, [
    globals.new_alarm_rules,
    globals.initial_alarm_rules,
    globals.alarm_rules_changed,
    setGlobal
  ]);

  const handleMonitoringChange = (
    inputId,
    isChecked
  ) => {
    const currentAlarmRules =
      globals.new_alarm_rules
        ? [...globals.new_alarm_rules]
        : [];

    if (isChecked) {
      const alreadyExists =
        currentAlarmRules.some(
          rule => Number(rule.INPUT_ID) === inputId
        );

      if (!alreadyExists) {
        const newAlarmRules = [
          ...currentAlarmRules,
          createDefaultAlarmRule(inputId)
        ];

        setGlobal(
          'new_alarm_rules',
          newAlarmRules
        );
      }
    } else {
      const newAlarmRules =
        currentAlarmRules.filter(
          rule => Number(rule.INPUT_ID) !== inputId
        );

      setGlobal(
        'new_alarm_rules',
        newAlarmRules
      );
    }

    setVariable(
      `GPIO_${inputId}`,
      isChecked ? "1" : "0"
    );
  };

  const handleAliasChange = (inputId, value) => {
    updateAlarmRuleField(
      inputId,
      'INPUT_NAME',
      value
    );
  };

  const handleAlertOnHighChange = (
    inputId,
    isChecked
  ) => {
    updateAlarmRuleField(
      inputId,
      'TRIGGER_TYPE',
      isChecked ? 0 : 1
    );
  };

  const handleSendRecoveryEmailChange = (
    inputId,
    isChecked
  ) => {
    updateAlarmRuleField(
      inputId,
      'SEND_RECOVERY_EMAIL',
      isChecked ? 1 : 0
    );
  };

  const handleDebounceChange = (
    inputId,
    value
  ) => {
    updateAlarmRuleField(
      inputId,
      'DEBOUNCE_TICKS',
      Number(value)
    );
  };

  const handleClearDelayChange = (
    inputId,
    value
  ) => {
    updateAlarmRuleField(
      inputId,
      'CLEAR_DELAY_TICKS',
      Number(value)
    );
  };

  const handleRetryProfileChange = (
    inputId,
    value
  ) => {
    updateAlarmRuleField(
      inputId,
      'RETRY_PROFILE_ID',
      Number(value)
    );
  };

  const retryPolicyOptions =
    globals.initial_retry_policies || [];

  /*
   * Always create 16 UI rows.
   *
   * If the INPUT_ID exists in new_alarm_rules:
   *   monitoring = true
   *   values come from that alarm rule.
   *
   * Otherwise:
   *   monitoring = false
   *   display default values.
   */
  const alarmRuleList = React.useMemo(() => {
    const currentAlarmRules =
      globals.new_alarm_rules || [];

    const rows = [];

    for (let i = 1; i <= 16; i++) {
      const existingRule =
        currentAlarmRules.find(
          rule => Number(rule.INPUT_ID) === i
        );

      const rule =
        existingRule ||
        createDefaultAlarmRule(i);

      rows.push({
        inputId: i,

        monitoring:
          Boolean(existingRule),

        alias:
          rule.INPUT_NAME ||
          `GPIO_${i}`,

        alertOnHigh:
          Number(rule.TRIGGER_TYPE) === 0,

        sendRecoveryEmail:
          Number(rule.SEND_RECOVERY_EMAIL) === 1,

        debounceTicks:
          Number(rule.DEBOUNCE_TICKS),

        clearDelayTicks:
          Number(rule.CLEAR_DELAY_TICKS),

        retryProfileId:
          Number(rule.RETRY_PROFILE_ID)
      });
    }

    return rows;
  }, [globals.new_alarm_rules]);

  if (globals.initial_alarm_rules === undefined) {
    return (
      <div>
      Loading...
      </div>
    )
  }

  return (
    <div className="container-fluid overflow-auto">
      <table className="table table-striped table-hover">
        <thead>
          <tr>
            <th>Line</th>
            <th>Name</th>
            <th>Alert on High</th>
            <th>Send Recovery Email</th>
            <th>Debounce</th>
            <th>Clear Delay</th>
            <th>Retry Policy</th>
            <th>Monitoring</th>
          </tr>
        </thead>

        <tbody>
          {alarmRuleList.map((rule) => (
            <tr key={rule.inputId}>

              <td>
                GPIO_{rule.inputId}
              </td>

              <td>
                <input
                  type="text"
                  className="form-control"
                  value={rule.alias}
                  disabled={!rule.monitoring}
                  onChange={(e) =>
                    handleAliasChange(
                      rule.inputId,
                      e.target.value
                    )
                  }
                />
              </td>

              <td>
                <div className="form-check form-switch">
                  <input
                    className="form-check-input"
                    type="checkbox"
                    id={`alert-on-high-${rule.inputId}`}
                    checked={rule.alertOnHigh}
                    disabled={!rule.monitoring}
                    onChange={(e) =>
                      handleAlertOnHighChange(
                        rule.inputId,
                        e.target.checked
                      )
                    }
                  />

                  <label
                    className="form-check-label"
                    htmlFor={`alert-on-high-${rule.inputId}`}
                  >
                    {rule.alertOnHigh ? "On" : "Off"}
                  </label>
                </div>
              </td>

              <td>
                <div className="form-check form-switch">
                  <input
                    className="form-check-input"
                    type="checkbox"
                    id={`send-recovery-${rule.inputId}`}
                    checked={rule.sendRecoveryEmail}
                    disabled={!rule.monitoring}
                    onChange={(e) =>
                      handleSendRecoveryEmailChange(
                        rule.inputId,
                        e.target.checked
                      )
                    }
                  />

                  <label
                    className="form-check-label"
                    htmlFor={`send-recovery-${rule.inputId}`}
                  >
                    {rule.sendRecoveryEmail ? "On" : "Off"}
                  </label>
                </div>
              </td>

              <td>
                <input
                  type="number"
                  className="form-control"
                  value={rule.debounceTicks}
                  disabled={!rule.monitoring}
                  onChange={(e) =>
                    handleDebounceChange(
                      rule.inputId,
                      e.target.value
                    )
                  }
                />
              </td>

              <td>
                <input
                  type="number"
                  className="form-control"
                  value={rule.clearDelayTicks}
                  disabled={!rule.monitoring}
                  onChange={(e) =>
                    handleClearDelayChange(
                      rule.inputId,
                      e.target.value
                    )
                  }
                />
              </td>

              <td>
                <select
                  className="form-select"
                  value={rule.retryProfileId}
                  disabled={!rule.monitoring}
                  onChange={(e) =>
                    handleRetryProfileChange(
                      rule.inputId,
                      e.target.value
                    )
                  }
                >
                  {retryPolicyOptions.map((policy) => (
                    <option
                      key={policy.RETRY_PROFILE_ID}
                      value={policy.RETRY_PROFILE_ID}
                    >
                      Policy {policy.RETRY_PROFILE_ID}
                    </option>
                  ))}
                </select>
              </td>

              <td>
                <div className="form-check form-switch">
                  <input
                    className="form-check-input"
                    type="checkbox"
                    id={`monitoring-${rule.inputId}`}
                    checked={rule.monitoring}
                    onChange={(e) =>
                      handleMonitoringChange(
                        rule.inputId,
                        e.target.checked
                      )
                    }
                  />

                  <label
                    className="form-check-label"
                    htmlFor={`monitoring-${rule.inputId}`}
                  >
                    {rule.monitoring ? "On" : "Off"}
                  </label>
                </div>
              </td>

            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

