m","position":{"x":1,"y":30},"size":{"width":38,"height":1130},"properties":{"code":"
// Return a React component. Available props:
//   properties, styles
//   variables, components, scripts, tables, commands, page
//   runEvent(type)              - fire a configured component event
//   setVariable(name, value)    - write a device variable
//   executeCommand(name, value) - run a device command
//   runScript(idOrName)         - run a page JavaScript script

function Component({
  variables,
  components,
  runEvent,
  executeCommand,
  setVariable,
  tables,
  globals,
  setGlobal,
  runScript,
  scripts
}) {

  const isAlarmActive = (value) => {
    return (
      value === true ||
      value === 1 ||
      value === "1" ||
      value === "true"
    );
  };

  const formatTimestamp = (timestamp) => {
    if (
      timestamp === null ||
      timestamp === undefined ||
      timestamp === ""
    ) {
      return "—";
    }

    // If timestamp is Unix seconds
    const numericTimestamp = Number(timestamp);

    if (
      !Number.isNaN(numericTimestamp) &&
      String(timestamp).trim() !== ""
    ) {
      const milliseconds =
        numericTimestamp < 1000000000000
          ? numericTimestamp * 1000
          : numericTimestamp;

      const date = new Date(milliseconds);

      if (!Number.isNaN(date.getTime())) {
        return date.toLocaleString();
      }
    }

    // Otherwise try parsing it directly as a date string
    const date = new Date(timestamp);

    if (!Number.isNaN(date.getTime())) {
      return date.toLocaleString();
    }

    // If parsing fails, just display the original value
    return String(timestamp);
  };

  const alarmRules =
    globals.new_alarm_rules ||
    globals.initial_alarm_rules ||
    [];

  const inputAlarmStates =
    globals.input_alarm_states || [];

  const getInputName = (inputId) => {
    const rule = alarmRules.find(
      rule => Number(rule.INPUT_ID) === Number(inputId)
    );

    return (
      rule?.INPUT_NAME ||
      `GPIO_${inputId}`
    );
  };

  const dashboardItems = React.useMemo(() => {
    return [...inputAlarmStates]
      .map(state => ({
        inputId: Number(state.INPUT_ID),

        inputName:
          getInputName(state.INPUT_ID),

        state:
          state.STATE,

        lastUpdatedTs:
          state.LAST_UPDATED_TS,

        alarmActive:
          isAlarmActive(state.ALARM_ACTIVE),

        alarmStartTs:
          state.ALARM_START_TS
      }))
      .sort(
        (a, b) =>
          a.inputId - b.inputId
      );

  }, [
    globals.input_alarm_states,
    globals.new_alarm_rules,
    globals.initial_alarm_rules
  ]);

  if (dashboardItems.length === 0) {
    return (
      <div className="container-fluid">
        <div className="alert alert-secondary">
          No input states available.
        </div>
      </div>
    );
  }

  return (
    <div className="container-fluid overflow-auto">
      <div className="row g-3">

        {dashboardItems.map((input) => (
          <div
            key={input.inputId}
            className="col-12 col-md-6 col-xl-4"
          >
            <div
              className={
                input.alarmActive
                  ? "card h-100 border-danger shadow-sm"
                  : "card h-100 shadow-sm"
              }
            >
              <div className="card-body">

                {/* Header */}
                <div className="d-flex justify-content-between align-items-start mb-3">

                  <div>
                    <div className="text-muted small">
                      GPIO_{input.inputId}
                    </div>

                    <h5 className="card-title mb-0">
                      {input.inputName}
                    </h5>
                  </div>

                  {input.alarmActive ? (
                    <span className="badge bg-danger fs-6">
                      ALARM ACTIVE
                    </span>
                  ) : (
                    <span className="badge bg-success">
                      Normal
                    </span>
                  )}

                </div>

                {/* State */}
                <div className="mb-3">
                  <div className="text-muted small">
                    Current State
                  </div>

                  <div className="fs-4 fw-bold text-truncate text-break w-100">
                    {input.state ?? "—"}
                  </div>
                </div>

                <hr />

                {/* Last update */}
                <div className="mb-2">
                  <div className="text-muted small">
                    Last Updated
                  </div>

                  <div>
                    {formatTimestamp(
                      input.lastUpdatedTs
                    )}
                  </div>
                </div>

                {/* Alarm start */}
                {input.alarmActive && (
                  <div className="mt-3">
                    <div className="text-danger small fw-bold">
                      Alarm Started
                    </div>

                    <div className="text-danger fw-bold">
                      {formatTimestamp(
                        input.alarmStartTs
                      )}
                    </div>
                  </div>
                )}

              </div>
            </div>
          </div>
        ))}

      </div>
    </div>
  );
}

return Component;
