/* Formats a duration as "H hours, M mins, S secs" into a caller-owned buffer.
 * Negative input is clamped to 0, oversized input to UINT32_MAX.
 * No allocation, no blocking, no shared state. Returns 0 or a negative errno. */
int seconds_to_hms(int64_t total_seconds, char *buf, size_t buf_len)
{
    /* Longest output: "1193046 hours, 59 mins, 59 secs" = 31 chars + NUL */
    const size_t min_len = 32U;
    uint32_t secs = 0U;
    uint32_t hours = 0U;
    uint8_t minutes = 0U;
    uint8_t seconds = 0U;
    int written = 0;

    if ((buf == NULL) || (buf_len < min_len)) {
        return -EINVAL;
    }
    buf[0] = '\0';

    if (total_seconds < 0) {
        secs = 0U;
    } else if (total_seconds > (int64_t)UINT32_MAX) {
        secs = UINT32_MAX;
    } else {
        secs = (uint32_t)total_seconds;
    }

    /* Divisors are non-zero constants */
    hours = secs / 3600U;
    minutes = (uint8_t)((secs % 3600U) / 60U);
    seconds = (uint8_t)(secs % 60U);

    if (hours > 0U) {
        written = snprintf(buf, buf_len, "%u hours, %u mins, %u secs",
                           (unsigned)hours, (unsigned)minutes, (unsigned)seconds);
    } else if (minutes > 0U) {
        written = snprintf(buf, buf_len, "%u mins, %u secs",
                           (unsigned)minutes, (unsigned)seconds);
    } else {
        written = snprintf(buf, buf_len, "%u secs", (unsigned)seconds);
    }

    return (written < 0) ? -EIO : 0;
}

char hms_buf[48] = {0};
if (seconds_to_hms((int64_t)({{$SECONDS}}), hms_buf, sizeof(hms_buf)) != 0) {
    LOG_WRN("seconds_to_hms failed");
}
hms = hms_buf;
